import { useEffect, useRef, useState } from 'react';
import styles from '../Home.module.css';
import { db } from '../firebaseConfig';
import { addDoc, collection, getDocs } from 'firebase/firestore';

export const Home = ({ companyList, setCompanyList }) => {
  const company = useRef();//ok
  const [select, setSelect] = useState("気になっている企業");//ok
  const [loading, setLoading] = useState(true)//データの読み込み状態を管理
  const [error, setError] = useState(null);

  const handleSelect = c => {
    setSelect(c.target.value);
  }//ok

  const handleAppCompany = async () => {
    const name = company.current.value;

    if (name === "") return;

    const docRef = await addDoc(collection(db, "companies"), {
      name: name,
      category: select,
      timestamp: new Date(),
      });
    //console.log("Document written with ID:", docRef.id);

    //firestoreへ追加後、ローカルの値を更新
    setCompanyList(prevList => {
      return [...prevList, { name, category: select, id: docRef.id }];
    });
    company.current.value = "";
  } 
  
  useEffect(() => {
    const fetchCompanies = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "companies"));
        const companiesDate = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setCompanyList(companiesDate);
      } catch (e) {
        console.error("Error fetching documents: ", e);
        setError("企業リスト読み込み中にエラーが発生しました。");
      }finally {
        setLoading(false);//読み込み終了
      }
    };
    fetchCompanies();
  }, [setCompanyList]);
  



  return (
    <div className="App">
      <header>
        <h1 className={styles.headTytle}>エントリー管理</h1>
      </header>
      <div className={styles.form}>
        <input type="text" placeholder='企業名を入力' ref={company} />
        <select onChange={handleSelect} value={select}>
          <option value="気になっている">気になっている企業</option>
          <option value="選考中/応募済み">選考中/応募済み企業</option>
          <option value="不合格">不合格になった企業</option>
        </select>
        <button onClick={handleAppCompany}>企業を追加</button>
      </div>

      <h3 className={styles.listTytle}>企業一覧</h3>
      <div className={styles.listContainer}>
        <ul>
          {companyList.length === 0 ? (
            <li className={styles.listLi}>登録がありません</li>
          ) : (
            companyList.map((c, i) => (
              <li key={c.id || i} className={styles.listLi}>{c.name} = {c.category} - {c.url}</li>
            ))
          )}
        </ul>
      </div>

    </div>
  );
}